import type {HandoffScope} from './cashier-handoff';
export type OpeningAction={id:string;scope:HandoffScope;reservation:string;kind:'application'|'external';source:string;target:string;clearing:string;externalKind:'recorded_collection'|'recorded_refund';period:string;date:string;amount:string;reference:string;reason:string};
export const openingUuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
export function openingCents(value:string){if(!/^(0|[1-9][0-9]{0,9})(\.[0-9]{1,2})?$/.test(value))throw Error('Enter a positive USD amount with at most two decimal places.');const [whole,fraction='']=value.split('.');const cents=BigInt(whole)*BigInt(100)+BigInt(fraction.padEnd(2,'0'));if(cents<=BigInt(0))throw Error('Amount must be positive.');return cents.toString()}
export function validateOpeningAction(p:OpeningAction,scope:HandoffScope,reservation:string){if(!p||p.scope?.tenant!==scope.tenant||p.scope?.property!==scope.property||p.scope?.actor!==scope.actor||p.reservation!==reservation||![p.id,p.source,p.period].every(openingUuid)||!['application','external'].includes(p.kind)||p.kind==='application'&&(!openingUuid(p.target)||p.target===p.source)||p.kind==='external'&&(!openingUuid(p.clearing)||!['recorded_collection','recorded_refund'].includes(p.externalKind))||typeof p.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||typeof p.amount!=='string'||!/^[1-9][0-9]{0,11}$/.test(p.amount)||typeof p.reason!=='string'||p.reason.trim()!==p.reason||p.reason.length<4||p.reason.length>500||p.kind==='external'&&(typeof p.reference!=='string'||p.reference.trim()!==p.reference||p.reference.length<4||p.reference.length>200))throw Error('Review the source, amount, accounts, date and reason.');}
export function readOpeningActionReceipt(v:Record<string,unknown>,p:OpeningAction){if(!v||v.request_id!==p.id||!openingUuid(v.journal_id)||typeof v.replayed!=='boolean'||(p.kind==='application'?v.external_payment!==false:v.processor_verified!==false))throw Error('Opening transaction receipt does not match this request.');}
